const fs=require('fs'),path=require('path'),cp=require('child_process'),crypto=require('crypto');
const base=__dirname,src=path.resolve(base,'../..'),results=[];
function setup(n){const r=path.join(base,'gov_r2_'+n);for(const d of ['tools','02_echipa','03_plan','05_validare','07_audit','09_jurnale'])fs.mkdirSync(path.join(r,d),{recursive:true});fs.copyFileSync(path.join(src,'tools/manage.cjs'),path.join(r,'tools/manage.cjs'));return r;}
function save(r,p,v){fs.writeFileSync(path.join(r,p),JSON.stringify(v,null,2));}
function run(r,args){const p=cp.spawnSync(process.execPath,[path.join(r,'tools/manage.cjs'),...args],{encoding:'utf8'});return {exit_code:p.status,stdout:p.stdout.trim(),stderr:p.stderr.trim().slice(0,700)};}
function probe(id,purpose,r,args){results.push({id,purpose,actual:run(r,args)});}
let r=setup('invalid_task');save(r,'02_echipa/roles.json',{roles:[{id:'MGR'},{id:'AUD-GOV'}]});save(r,'03_plan/tasks.json',{tasks:[{id:'W-X',owner:'NONEXISTENT',auditor:'FAKE',status:'accepted',dependencies:[],outputs:[],experiments:['EX-MISSING'],acceptance:'criterion',next_action:'done',attempt:0}]});probe('GOV2-T01','Original invalid task must fail',r,['validate']);
r=setup('invalid_requirements');save(r,'03_plan/requirements.json',{requirements:[{id:'R1',tests:['E1']}]});save(r,'05_validare/experiments.json',{experiments:[{id:'E1',requirements:[],metric:'m',target:'t',protocol:'p',sample:'s',owner:'A',auditor:'A'}]});probe('GOV2-T02','Original incomplete/uncorrelated requirements must fail',r,['validate']);
r=setup('missing_audit');save(r,'07_audit/REGISTRU.json',{status:'accepted',required_domains:['AUD-GOV'],findings:[]});probe('GOV2-T03','Original missing review must fail',r,['validate']);
r=setup('hidden_finding');fs.writeFileSync(path.join(r,'07_audit/review.md'),'# Review\nVersion identified in fixture.');save(r,'07_audit/domain_findings.json',[{id:'X',status:'open',severity:'P1'}]);save(r,'07_audit/REGISTRU.json',{status:'accepted',required_domains:['AUD-GOV'],findings:[],reviews:[{domain:'AUD-GOV',status:'accepted',author_agent:'writer',auditor_agent:'reviewer',report:'07_audit/review.md',findings_ref:'07_audit/domain_findings.json'}]});probe('GOV2-T04','Accepted domain with open referenced finding must fail',r,['validate']);
r=setup('missing_event');probe('GOV2-T05','Missing basic event must fail without write',r,['event','actor']);results.at(-1).journal_created=fs.existsSync(path.join(r,'09_jurnale/actor.jsonl'));
r=setup('bad_structured');save(r,'input.json',{actor:'actor',task:'W00',event:'checkpoint',result:'done',artifacts:[42],next:'resume',attempt:1,input_hashes:{'nonexistent':'banana'},checks:[false]});probe('GOV2-T06','Structured malformed element types and hash must fail',r,['event-json',path.join(r,'input.json')]);probe('GOV2-T07','Malformed structured emitted event validation',r,['validate']);
r=setup('valid_structured');const artifact='evidence.txt';fs.writeFileSync(path.join(r,artifact),'fixture input');const h=crypto.createHash('sha256').update('fixture input').digest('hex');save(r,'input.json',{actor:'actor',task:'W00',event:'checkpoint',result:'input verified',artifacts:[artifact],next:'independent review',attempt:1,input_hashes:{[artifact]:h},checks:[{id:'CHECK1',status:'passed',evidence:artifact}]});probe('GOV2-T08','Valid structured checkpoint must pass',r,['event-json',path.join(r,'input.json')]);probe('GOV2-T09','Valid structured log validates',r,['validate']);
r=setup('tmp');fs.writeFileSync(path.join(r,'interrupted.tmp'),'uncommitted');probe('GOV2-T10','Tmp blocks documentary validate',r,['validate']);probe('GOV2-T11','Manifest includes tmp',r,['manifest']);probe('GOV2-T12','Same tree verifies after manifest',r,['verify']);
r=setup('positive_registers');fs.writeFileSync(path.join(r,'evidence.txt'),'fixture proof');fs.writeFileSync(path.join(r,'07_audit/review.md'),'# Accepted fixture review');save(r,'02_echipa/roles.json',{roles:[{id:'MGR'},{id:'AUD-GOV'}]});save(r,'05_validare/experiments.json',{experiments:[{id:'E1',requirements:['R1'],metric:'m',target:'t',protocol:'p',sample:'s',owner:'MGR',auditor:'AUD-GOV',status:'planned',result:null}]});save(r,'03_plan/requirements.json',{requirements:[{id:'R1',owner:'MGR',acceptance:'t',tests:['E1']}]});save(r,'03_plan/tasks.json',{tasks:[{id:'DOC-X',owner:'MGR',auditor:'AUD-GOV',status:'accepted',dependencies:[],outputs:['evidence.txt'],acceptance:'criterion',next_action:'resume W00',attempt:1,audit_ref:'07_audit/review.md',accepted_at:new Date().toISOString(),acceptance_evidence:['evidence.txt']}]});save(r,'07_audit/REGISTRU.json',{status:'accepted',required_domains:['AUD-GOV'],findings:[],reviews:[{domain:'AUD-GOV',status:'accepted',author_agent:'writer',auditor_agent:'reviewer',report:'07_audit/review.md'}]});probe('GOV2-T13','Valid reciprocal planned experiment and accepted document task',r,['validate']);
r=setup('actual_legacy_logs');for(const f of fs.readdirSync(path.join(src,'09_jurnale')).filter(f=>f.endsWith('.jsonl')))fs.copyFileSync(path.join(src,'09_jurnale',f),path.join(r,'09_jurnale',f));probe('GOV2-T14','Actual current legacy log copies remain valid',r,['validate']);
fs.writeFileSync(path.join(base,'governance_r2_results.json'),JSON.stringify({at:new Date().toISOString(),scope:'isolated fixtures; no main register changes',results},null,2));console.log(JSON.stringify(results));

